package android.graphics;
import java.awt.image.BufferedImage;
public class Bitmap {public final BufferedImage image;final java.util.Map<Float,BufferedImage> variants=new java.util.HashMap<>();public enum Config{ARGB_8888}public Bitmap(BufferedImage b){image=b;}public int getWidth(){return image.getWidth();}public int getHeight(){return image.getHeight();}public int getAllocationByteCount(){return getWidth()*getHeight()*4;}public static Bitmap createBitmap(int[] pixels,int w,int h,Config c){BufferedImage b=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);b.setRGB(0,0,w,h,pixels,0,w);return new Bitmap(b);}BufferedImage filtered(ColorFilter f){if(!(f instanceof ColorMatrixColorFilter))return image;float s=((ColorMatrixColorFilter)f).saturation;return variants.computeIfAbsent(s,key->{int w=getWidth(),h=getHeight();int[] pixels=image.getRGB(0,0,w,h,null,0,w);for(int i=0;i<pixels.length;i++){int c=pixels[i],r=c>>16&255,g=c>>8&255,b=c&255;float l=.213f*r+.715f*g+.072f*b;pixels[i]=(c&0xff000000)|(Math.round(l+(r-l)*s)<<16)|(Math.round(l+(g-l)*s)<<8)|Math.round(l+(b-l)*s);}BufferedImage out=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);out.setRGB(0,0,w,h,pixels,0,w);return out;});}}
